for filename, (title, subtitle, legal, sections) in DOCS.items():
    story = [Paragraph(escape(title), styles["TitleN"]), Paragraph(escape(subtitle), styles["SubN"])]
    if legal:
        story.append(Paragraph("ПРЕДВАРИТЕЛЬНЫЙ ПРОЕКТ. Не считать окончательным юридическим документом до заполнения реквизитов и проверки фактических процессов.", styles["WarnN"]))
    for heading, paragraphs in sections:
        story.append(Paragraph(escape(heading), styles["HeadN"]))
        for paragraph in paragraphs:
            story.append(Paragraph(escape(paragraph), styles["BodyN"]))
    pdf = SimpleDocTemplate(str(BASE / filename), pagesize=A4, rightMargin=18*mm, leftMargin=18*mm, topMargin=17*mm, bottomMargin=17*mm, title=title, author="NEXORA")
    pdf.build(story)
print("Generated", len(DOCS), "NEXORA PDF documents")
